#!/usr/bin/env node
/**
 * Simulation study: how good is Vigía's detection logic when the truth is known?
 * Estudio de simulación: ¿qué tan buena es la lógica de detección cuando se conoce la verdad?
 *
 * Runs the REAL FatigueMonitor (web/js/fatigue.js) on synthetic drivers whose eye
 * closures, yawns and nods are generated by scripts/lib/synthetic.mjs, and measures:
 *   E1  closed-eye threshold × sensor noise → blink / long-closure detection, PERCLOS error
 *   E2  frame rate (5–30 fps)               → what a slow phone or the Haar engine loses
 *   E3  personal calibration vs fixed threshold, across people with different eye shapes
 *   E4  per-minute score vs latent fatigue  → is the score informative? (ablation, timing)
 *
 * Usage / Uso:  node scripts/simulation_study.mjs   (≈ 1–2 min)
 * Output:       analysis/results/simulation/*.csv + meta.json
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { FatigueMonitor } from '../web/js/fatigue.js';
import { APP_VERSION, DEFAULTS } from '../web/js/config.js';
import { fatigueAt, frames, generateTimeline, makeDriver } from './lib/synthetic.mjs';

const OUT = resolve('analysis/results/simulation');
const started = Date.now();

function toCSV(rows) {
  const cols = Object.keys(rows[0]);
  const fmt = (v) => (v == null || (typeof v === 'number' && !Number.isFinite(v)) ? '' : typeof v === 'number' ? Number(v.toFixed(5)) : v);
  return [cols.join(','), ...rows.map((r) => cols.map((c) => fmt(r[c])).join(','))].join('\n') + '\n';
}

/** One-to-one matching of true episodes to detected events inside [start, end + tol]. */
function match(truth, detected, tol) {
  const used = new Array(detected.length).fill(false);
  let tp = 0;
  const latencies = [];
  let j0 = 0;
  for (const tr of truth) {
    while (j0 < detected.length && detected[j0].driveT < tr.start) j0++;
    for (let j = j0; j < detected.length && detected[j].driveT <= tr.end + tol; j++) {
      if (!used[j]) {
        used[j] = true;
        tp++;
        latencies.push(detected[j].driveT - tr.start);
        break;
      }
    }
  }
  return { tp, fn: truth.length - tp, fp: used.filter((u) => !u).length, latencies };
}

const overlaps = (e, list) => list.some((x) => x.start < e.end + 300 && x.end > e.start - 300);

/** Run one drive and score it against the ground truth. */
function runDrive(d, { fps = 30, config = {}, noiseScale = 1, perMinute = false } = {}) {
  const tl = generateTimeline(d);
  const monitor = new FatigueMonitor(config);
  monitor.startCalibration(0);
  const events = [];
  const perclos = [];
  const minutes = new Map();
  const win = [];
  let head = 0;
  let closedCount = 0;
  let nextMinute = 60_000;

  for (const { sig, truth } of frames(d, tl, fps, noiseScale)) {
    const snap = monitor.update(sig);
    for (const e of snap.events) events.push({ ...e, driveT: e.t - tl.calibrationMs });
    if (truth.driveT < 0) continue;
    // Ground-truth PERCLOS (P80: eyelid ≥ 80 % closed) over the same 60 s window.
    if (!truth.lost) {
      const c = truth.depth >= 0.8 ? 1 : 0;
      win.push({ t: truth.driveT, c });
      closedCount += c;
    }
    while (head < win.length && win[head].t < truth.driveT - 60_000) closedCount -= win[head++].c;
    if (truth.driveT >= nextMinute) {
      const n = win.length - head;
      perclos.push({ truth: n ? closedCount / n : null, est: snap.perclos });
      nextMinute += 60_000;
    }
    if (perMinute && snap.phase === 'monitoring') {
      const mi = Math.floor(truth.driveT / 60_000);
      const a = minutes.get(mi) ?? { n: 0, f: 0, score: 0, scoreMax: 0, levelMax: 0, perclos: null, blink: null };
      a.n += 1;
      a.f += truth.f;
      a.score += snap.score;
      a.scoreMax = Math.max(a.scoreMax, snap.score);
      a.levelMax = Math.max(a.levelMax, snap.levelIndex);
      a.perclos = snap.perclos;
      a.blink = snap.avgBlinkMs;
      minutes.set(mi, a);
    }
  }

  const tol = 2 * (1000 / fps) + 60;
  const valid = (e) => e.start >= 0 && !overlaps(e, tl.faceLost);
  const det = (type) => events.filter((e) => e.type === type && e.driveT >= 0);
  const trueBlinks = tl.closures.filter((c) => c.kind === 'blink' && valid(c));
  const trueLong = tl.closures.filter((c) => c.kind === 'long' && valid(c));
  const trueCrit = trueLong.filter((c) => c.dur >= DEFAULTS.criticalClosureMs + 2 * (1000 / fps));
  const blinks = match(trueBlinks, det('blink'), tol);
  const long = match(trueLong, det('long_closure'), tol);
  const crit = match(trueCrit, det('critical_closure'), tol);
  const yawns = match(tl.yawns.filter(valid), det('yawn'), 1000);
  const heads = match(tl.nods.filter(valid), det('head_deviation'), 500);
  const pc = perclos.filter((p) => p.truth != null && p.est != null);
  const hours = tl.total / 3_600_000;
  const mean = (a) => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : null);

  const summary = {
    driver: d.id,
    base_ear: d.baseEar,
    noise: d.noise,
    hours,
    blink_tp: blinks.tp,
    blink_fn: blinks.fn,
    blink_fp: blinks.fp,
    long_tp: long.tp,
    long_fn: long.fn,
    long_fp: long.fp,
    crit_n: trueCrit.length,
    crit_tp: crit.tp,
    crit_latency_ms: mean(crit.latencies),
    yawn_tp: yawns.tp,
    yawn_fn: yawns.fn,
    yawn_fp: yawns.fp,
    head_tp: heads.tp,
    head_fn: heads.fn,
    head_fp: heads.fp,
    perclos_mae: mean(pc.map((p) => Math.abs(p.est - p.truth))),
    perclos_bias: mean(pc.map((p) => p.est - p.truth)),
  };
  const minuteRows = [...minutes.entries()].map(([mi, a]) => ({
    driver: d.id,
    minute: mi,
    f_mean: a.f / a.n,
    score_mean: a.score / a.n,
    score_max: a.scoreMax,
    level_max: a.levelMax,
    perclos: a.perclos,
    avg_blink_ms: a.blink,
    long_closures: events.filter((e) => e.type === 'long_closure' && Math.floor(e.driveT / 60_000) === mi).length,
    yawns: events.filter((e) => e.type === 'yawn' && Math.floor(e.driveT / 60_000) === mi).length,
  }));
  return { summary, minuteRows };
}

const drivers = (n, seed0, overrides = {}) =>
  Array.from({ length: n }, (_, i) => makeDriver(i + 1, seed0 + i, overrides));

mkdirSync(OUT, { recursive: true });
const log = (s) => console.log(`[${((Date.now() - started) / 1000).toFixed(0)} s] ${s}`);

// E1 — threshold × noise
const e1 = [];
const groupA = drivers(12, 1000);
for (const noiseScale of [1, 2]) {
  for (const ratio of [0.5, 0.55, 0.6, 0.65, 0.7, 0.75, 0.8, 0.85]) {
    for (const d of groupA) {
      e1.push({ ratio, noise_scale: noiseScale, ...runDrive(d, { config: { eyeClosedRatio: ratio }, noiseScale }).summary });
    }
  }
  log(`E1 noise ×${noiseScale} done`);
}
writeFileSync(`${OUT}/e1_thresholds.csv`, toCSV(e1));

// E2 — frame rate
const e2 = [];
for (const fps of [5, 10, 15, 20, 30]) {
  for (const d of groupA) e2.push({ fps, ...runDrive(d, { fps }).summary });
  log(`E2 ${fps} fps done`);
}
writeFileSync(`${OUT}/e2_fps.csv`, toCSV(e2));

// E3 — personal calibration vs fixed absolute threshold, across eye shapes
const e3 = [];
const groupB = drivers(12, 2000).map((d, i) => ({ ...d, baseEar: 0.22 + (0.12 * i) / 11 }));
for (const d of groupB) {
  e3.push({ method: 'personal', ...runDrive(d).summary });
  e3.push({ method: 'fixed_0.20', ...runDrive(d, { config: { useBaselineForEyes: false } }).summary });
}
log('E3 done');
writeFileSync(`${OUT}/e3_calibration.csv`, toCSV(e3));

// E4 — per-minute score vs latent fatigue (30 drivers × 30 min)
const e4 = [];
const e4Drivers = drivers(30, 3000, { minutes: 30 });
for (const d of e4Drivers) e4.push(...runDrive(d, { perMinute: true }).minuteRows);
log('E4 done');
writeFileSync(`${OUT}/e4_minutes.csv`, toCSV(e4));
writeFileSync(
  `${OUT}/e4_drivers.csv`,
  toCSV(e4Drivers.map((d) => ({ driver: d.id, base_ear: d.baseEar, noise: d.noise, onset_min: d.onsetMin, f_max: d.fMax }))),
);

writeFileSync(
  `${OUT}/meta.json`,
  JSON.stringify(
    {
      app_version: APP_VERSION,
      generated: new Date().toISOString(),
      runtime_s: Math.round((Date.now() - started) / 1000),
      seeds: { e1_e2: 1000, e3: 2000, e4: 3000 },
      experiments: {
        e1: '12 drivers × 20 min × 8 thresholds × 2 noise levels, 30 fps',
        e2: '12 drivers × 20 min × 5 frame rates, default threshold',
        e3: '12 drivers (open-eye EAR 0.22–0.34) × personal vs fixed threshold',
        e4: '30 drivers × 30 min, per-minute aggregation',
      },
      defaults: DEFAULTS,
      fatigueAt: fatigueAt.toString(),
    },
    null,
    2,
  ),
);
log(`Wrote results to ${OUT}`);
